INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- `public`: すべてのクラスからアクセス可能です\n- `protected`: 同じパッケージ内のすべてのクラスおよびサブクラスからアクセス可能です\n- **(default) パッケージ・プライベート**: アクセス修飾子を明示しない場合の設定で、同じパッケージ内でのみアクセス可能です\n- `private`: 同じクラス内でのみアクセス可能であり、他のクラスからはアクセスできません', 17, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
