INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- **カプセル化**: データの隠蔽とオブジェクト間の相互作用を最小限に抑えるため\n- **保守性**: 外部からアクセス可能な範囲を明確に定義することで、コードの安定性を確保するため\n- **拡張性**: `protected`を活用し、サブクラスから必要なメンバーのみアクセス可能にすることで柔軟な設計を可能にするため', 21, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
