INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"markdown","code":"  ~/Documents/java_study/main ❯ javap -c OuterClass$InnerClass.class                                     at  03:02:34 PM\\nCompiled from \\"OuterClass.java\\"\\npublic class OuterClass {\\n  public OuterClass();\\n    Code:\\n       0: aload_0\\n       1: invokespecial #1                  // Method java/lang/Object.\\"<init>\\":()V\\n       4: aload_0\\n       5: ldc           #7                  // String Private Field\\n       7: putfield      #9                  // Field privateField:Ljava/lang/String;\\n      10: return\\n\\n  public static void main(java.lang.String[]);\\n    Code:\\n       0: new           #10                 // class OuterClass\\n       3: dup\\n       4: invokespecial #15                 // Method \\"<init>\\":()V\\n       7: astore_1\\n       8: new           #16                 // class OuterClass$InnerClass\\n      11: dup\\n      12: aload_1\\n      13: dup\\n      14: invokestatic  #18                 // Method java/util/Objects.requireNonNull:(Ljava/lang/Object;)Ljava/lang/Object;\\n      17: pop\\n      18: invokespecial #24                 // Method OuterClass$InnerClass.\\"<init>\\":(LOuterClass;)V\\n      21: astore_2\\n      22: aload_2\\n      23: invokevirtual #27                 // Method OuterClass$InnerClass.printPrivateField:()V\\n      26: return\\n}\\n\\n  ~/Documents/java_study/main ❯ javap -c OuterClass.class                                                at  03:02:43 PM\\nCompiled from \\"OuterClass.java\\"\\npublic class OuterClass {\\n  public OuterClass();\\n    Code:\\n       0: aload_0\\n       1: invokespecial #1                  // Method java/lang/Object.\\"<init>\\":()V\\n       4: aload_0\\n       5: ldc           #7                  // String Private Field\\n       7: putfield      #9                  // Field privateField:Ljava/lang/String;\\n      10: return\\n\\n  public static void main(java.lang.String[]);\\n    Code:\\n       0: new           #10                 // class OuterClass\\n       3: dup\\n       4: invokespecial #15                 // Method \\"<init>\\":()V\\n       7: astore_1\\n       8: new           #16                 // class OuterClass$InnerClass\\n      11: dup\\n      12: aload_1\\n      13: dup\\n      14: invokestatic  #18                 // Method java/util/Objects.requireNonNull:(Ljava/lang/Object;)Ljava/lang/Object;\\n      17: pop\\n      18: invokespecial #24                 // Method OuterClass$InnerClass.\\"<init>\\":(LOuterClass;)V\\n      21: astore_2\\n      22: aload_2\\n      23: invokevirtual #27                 // Method OuterClass$InnerClass.printPrivateField:()V\\n      26: return\\n}"}', 50, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
