INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- 内部クラスは必ず外部クラスの参照を必要とします\n- 外部クラスなしでは、内部クラス単独で動作することはできません\n- 内部クラスは外部クラスの `private` フィールドやメソッドにアクセスできます', 60, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
