INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_NUMBERED', '1. **論理的に一箇所でのみ使用されるクラスをグループ化する方法**:\n\n   - もしあるクラスが他の特定のクラスでのみ有用である場合、そのクラスを対象のクラス内に含め、両者を一緒に維持することが理にかなっています。\n   - このような **ヘルパークラス（helper class）** をネストすることで、パッケージがより簡潔になります。', 62, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_NUMBERED', '2. **カプセル化を向上させる**:\n\n   - 2つのトップレベルクラス A と B を考えてみましょう。B が本来 `private` として宣言されるべき A のメンバーにアクセスする必要がある場合、B を A 内に隠すことで、A のメンバーを `private` に保ちながらも B がアクセスできるようになります\n   - また、B 自体も外部から隠すことが可能です\n\n   ```java\n   public class A {\n       private String privateFiled = "haroya";\n   \n       public class B {\n           public void printPrivateFiled() {\n               System.out.printlnf("print : " + privateFiled);\n           }\n       }\n   \n    public static void main(String[] args) {\n       A a = new A();\n       A.B b = a.new B();\n       b.printPrivateFiled(); // Aの private メンバーにアクセス\n   }\n   ```', 63, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_NUMBERED', '3. **コードの可読性と保守性を向上させる**:\\\n   トップレベルクラス内に小さなクラスをネストすることで、そのコードが使用される場所により近くなり、可読性と保守性が向上します', 64, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
