INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"markdown","code":"  ~/Documents/java_study/main ❯ javap -c Haroya.class                                                                            at  03:37:38 PM\\nCompiled from \\"Haroya.java\\"\\npublic class Haroya {\\n  public Haroya();\\n    Code:\\n       0: aload_0\\n       1: invokespecial #1                  // Method java/lang/Object.\\"<init>\\":()V\\n       4: return\\n\\n  public void sayHello();\\n    Code:\\n       0: new           #7                  // class Haroya$1HelloWorld\\n       3: dup\\n       4: aload_0\\n       5: invokespecial #9                  // Method Haroya$1HelloWorld.\\"<init>\\":(LHaroya;)V\\n       8: astore_1\\n       9: aload_1\\n      10: invokevirtual #12                 // Method Haroya$1HelloWorld.printMessage:()V\\n      13: return\\n\\n  public static void main(java.lang.String[]);\\n    Code:\\n       0: new           #15                 // class Haroya\\n       3: dup\\n       4: invokespecial #17                 // Method \\"<init>\\":()V\\n       7: astore_1\\n       8: aload_1\\n       9: invokevirtual #18                 // Method sayHello:()V\\n      12: return\\n}\\n\\n  ~/Documents/java_study/main ❯ javap -c Haroya\\\\$1HelloWorld                                                                     at  03:37:50 PM\\nCompiled from \\"Haroya.java\\"\\nclass Haroya$1HelloWorld {\\n  final Haroya this$0;\\n\\n  Haroya$1HelloWorld(Haroya);\\n    Code:\\n       0: aload_0\\n       1: aload_1\\n       2: putfield      #1                  // Field this$0:LHaroya;\\n       5: aload_0\\n       6: invokespecial #7                  // Method java/lang/Object.\\"<init>\\":()V\\n       9: return\\n\\n  void printMessage();\\n    Code:\\n       0: getstatic     #13                 // Field java/lang/System.out:Ljava/io/PrintStream;\\n       3: ldc           #19                 // String Hello, World!\\n       5: invokevirtual #21                 // Method java/io/PrintStream.println:(Ljava/lang/String;)V\\n       8: return\\n}"}', 78, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
