INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- 外部クラスの情報を暗黙的に把握しています。\n  - 内部クラスは外部クラスのすべてのメンバー（`private` を含む）に直接アクセス可能です。\n  - 外部クラスのインスタンスを明示的に参照しなくても、外部クラスのメンバーにアクセスできます。', 86, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
