INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- 外部クラスの参照を明示的に保存します。\n  - ローカルクラスは `this$0` フィールドを通じて外部クラスの情報に間接的にアクセスします。\n    - 外部クラスの参照をコンストラクタの引数のように受け取り、利用します。\n  - 定義されたブロック内のローカル変数や引数をキャプチャして使用します（ただし、それらは `final` または「事実上の`final`」である必要があります）。', 88, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
