INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'スタック内のメソッドは命令が終了するとライフサイクルに従って消えますが、\\\nヒープメモリに生成されたオブジェクトはGC（ガベージコレクション）が実行されるまで再利用可能です。', 111, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '例えば、複数のスレッドを生成してヒープ上のオブジェクトを参照する場合、\\\nその変数が `final` でないと値が変更され続けるため、オブジェクトの整合性を保証できません。\\\nそのため、Javaでは `final` を使用して値をコピーする方法が採用されています。', 112, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '以下のコードは、`ThreadExample` クラスの例で、ローカル変数がスレッド間で共有される状況を示しています。', 113, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\npublic class ThreadExample {\\n    public void method() {\\n        String message = \\"こんにちは\\";  // スタック上のローカル変数\\n\\n        // 1. 最初のスレッド\\n        new Thread(() -> {\\n            // message がヒープにコピーされて保存される\\n            System.out.println(\\"スレッド1: \\" + message);\\n        }).start();\\n\\n        // 2. 二番目のスレッド\\n        new Thread(() -> {\\n            // 同じ message を使用\\n            System.out.println(\\"スレッド2: \\" + message);\\n        }).start();\\n\\n        // メソッドが終了してもスレッドは実行を継続する！\\n    }\\n}"}', 114, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '上記の例のようなコードは許容されますが、ローカルスコープ（`{}`）内で値を変更しようとすると、', 115, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\n    new Thread(() -> {\\n        System.out.println(\\"スレッド1 \\" + message);\\n        message = \\"안녕하세요\\";\\n    }).start();"}', 116, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '2番目のスレッドでは、`message` の一貫性を保証することができません。', 117, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
