INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\ninterface Printable {\\n    void print();\\n}\\n\\nclass OuterClass {\\n    void method() {\\n        // インターフェースやクラスをその場で実装\\n        Printable printable = new Printable() {\\n            public void print() {\\n                System.out.println(\\"匿名クラス\\");\\n            }\\n        };\\n\\n        printable.print();\\n    }\\n}"}', 120, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
