INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'Testクラスのバイトコードを見ると、`getStatic` や `putStatic` という記述が出てきますが、\\\nJVM標準文書を検索してみると、より詳しい情報を得ることができました。', 141, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '`getStatic` を例に取ると、静的（static）フィールドを取得してスタックにプッシュする命令と記載されていました。', 142, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'なぜなら、JVM内で Method Area に静的変数（static フィールド）が既に保存されているため、\\\nクラスレベルでメモリに一つだけ存在し、その値を取得してスタック（Javaの命令実行、Javaはスタックベース）に載せるためです。', 143, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '要約すると、JVMの Method Area に静的（static）フィールドが保存されているため、\\\nクラスレベルで一つだけ存在し、必要に応じてスタックに載せて使用されるということです。', 144, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
