INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- **Method Area（Static Area）**\n\n  - `static` メンバーが保存される領域\n  - プログラム開始時に生成され、終了時に破棄される\n  - すべてのスレッドで共有される\n  - `static` 変数、`static` メソッド、クラス情報などが保存される', 147, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- **Heap**\n\n  - インスタンス（オブジェクト）が保存される領域\n  - `new` 演算子で生成されたオブジェクトやインスタンス変数が保存される\n  - GC（ガベージコレクション）の対象', 148, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
