INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\npublic class Singleton {\\n    private static final Singleton instance;\\n\\n    // 静的ブロックで初期化\\n    static {\\n        try {\\n            instance = new Singleton();\\n        } catch (Exception e) {\\n            throw new RuntimeException();\\n        }\\n    }\\n\\n    // private コンストラクタ\\n    private Singleton() {\\n        // 初期化作業\\n    }\\n\\n    public static Singleton getInstance() {\\n        return instance;\\n    }\\n}"}', 192, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
