INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'QUOTE', 'The Java Virtual Machine uses local variables to pass parameters on method invocation. On class method invocation, any parameters are passed in consecutive local variables starting from local variable 0. On instance method invocation, local variable 0 is always used to pass a reference to the object on which the instance method is being invoked (this in the Java programming language). Any parameters are subsequently passed in consecutive local variables starting from local variable 1.', 219, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- Java仮想マシン（JVM）は、メソッドを呼び出す際にローカル変数を使用してパラメータを渡します。\\\n  クラスメソッドを呼び出す場合、すべてのパラメータは0番目のローカル変数から順に連続して格納されます。\\\n  インスタンスメソッドを呼び出す場合、常に0番目のローカル変数には、呼び出しているオブジェクトの参照（Javaでは`this`）が格納されます。\\\n  その後、パラメータは1番目のローカル変数から順に格納されます', 220, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
