INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'QUOTE', 'インスタンスメソッドを呼び出す場合、常に0番目のローカル変数には、呼び出しているオブジェクトの参照（Javaでは`this`）が格納されます。', 229, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- **オブジェクトの参照をスタックにロードする際に**`this`**を使用します。**\n- **インスタンスメソッドは、インスタンスフィールドや他のインスタンスメソッドにアクセスする際、**`this`**を通じてスタックにロードします。**', 230, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'デフォルトコンストラクタの場合、以前説明したように親クラスのメソッド（`Object` のコンストラクタ）を呼び出すため、\\\n`this` の参照をスタックにロードします。', 231, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'ただし、JVMでは `this` を自動的に呼び出すため、', 232, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\npublic class Test {\\n\\n    private int num = 0;\\n\\n    public Test(int a) {\\n        // this が隠れている\\n        // super も隠れている\\n        num = a;\\n    }\\n}"}', 233, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
