INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\npublic static void staticMethod();\\n    Code:\\n       0: getstatic     #13                 // Field staticInt:I\\n       3: iconst_1\\n       4: iadd\\n       5: putstatic     #13                 // Field staticInt:I\\n       8: return"}', 235, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '一方で、`static` メソッドでは `this` を介して呼び出すことはありません。\\\nなぜなら、`static` メソッドは既に JVMランタイムの Method Area にロードされており、\\\nスタックにロードする必要がないためです。', 236, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/1d9079e5-b4a8-0217-b97f-380001abefae.png","alt":"image.png"}', 237, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '公式ドキュメントを参照すると、次のように記載されています：', 238, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'QUOTE', 'A method that is declared static is called a class method.\\\nクラスメソッドは特定のオブジェクトへの参照なしに常に呼び出されます。', 239, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- `static` と宣言されたメソッドは特定のオブジェクトとは関連せず、クラス自体に属するメソッドです。\n- そのため、オブジェクトを作成せずとも直接呼び出すことができます', 240, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'QUOTE', 'static メソッド内では `this` や `super` のようなキーワードは使用できません。\\\nなぜなら、これらのキーワードは特定のオブジェクト（現在のオブジェクト）を指すものですが、static メソッドはオブジェクトなしで呼び出されるためです。', 241, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'DIVIDER', NULL, 242, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '改めて定義すると、`this` とは以下の通りです：', 243, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- `this` は参照をスタックにロードするために使用されます', 244, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'QUOTE', 'ℹ️ **Note**\\\nJVMのメソッド呼び出し規約によれば、インスタンスメソッドでは最初のローカル変数スロットに `this` が格納されます。\\\nスタックに `this` をロードすることで、メソッドがオブジェクトの状態に基づいて動作することを可能にしています。\\\nインスタンスメソッドのバイトコード実行時に最初の命令として `aload_0` によって `this` をスタックに載せるのも、この規約によるものです。', 245, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- 内部オブジェクトが存在せず、内部インスタンスにアクセスする必要がない場合、`javac` コンパイラでは `this` が生成されません。\\\n  （例: オブジェクト参照をスタックにロードする必要がない状況）', 246, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
