INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '`String` は定数プールに格納され、命令は Method Area から取得されるため、\\\n内部インスタンスを参照する必要がありません。\\\nそのため、`aload_0`（`this`）が生成されません。', 250, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
