INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- コンストラクタは特別なメソッドであり、メソッドのようにオーバーロードをサポートします。\n- `this` は自分自身のインスタンスを参照するときに使用されます。', 259, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'これらの2つの特性を利用して、コンストラクタが自分自身の別のコンストラクタを呼び出すことができます。\\\nこれを **コンストラクタチェイニング** と呼びます。', 260, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\npublic class コンストラクタチェイニング {\\n    private int count;\\n    private String name;\\n\\n    // デフォルトコンストラクタ\\n    public コンストラクタチェイニング() {\\n        this(0, \\"default\\"); // 別のコンストラクタを呼び出し\\n    }\\n\\n    // 引数が1つのコンストラクタ\\n    public コンストラクタチェイニング(int count) {\\n        this(count, \\"default\\"); // 別のコンストラクタを呼び出し\\n    }\\n\\n    // 引数が2つのコンストラクタ\\n    public コンストラクタチェイニング(int count, String name) {\\n        this.count = count;\\n        this.name = name;\\n    }\\n}"}', 261, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
