INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\npublic class Person {\\n    private String name;\\n    private int age;\\n\\n    public Person setName(String name) {\\n        this.name = name;\\n        return this;  // 現在のインスタンスを返すことでメソッドチェイニングが可能    \\n        }\\n\\n    public Person setAge(int age) {\\n        this.age = age;\\n        return this; // 現在のインスタンスを返すことでメソッドチェイニングが可能\\n    }\\n}\\n\\n// 使用例\\nPerson person = new Person().setName(\\"Alice\\").setAge(25);"}', 264, NOW(6), NOW(6) FROM posts WHERE id = 114 AND slug = 'java-6' AND updated_at = '2026-07-15 15:18:25.820559';
