INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"java","code":"class ArithmeticDemo {\\n\\n    public static void main (String[] args) {\\n\\n        int result = 1 + 2;\\n        // result is now 3\\n        System.out.println(\\"1 + 2 = \\" + result);\\n        int original_result = result;\\n\\n        result = result - 1;\\n        // result is now 2\\n        System.out.println(original_result + \\" - 1 = \\" + result);\\n        original_result = result;\\n\\n        result = result * 2;\\n        // result is now 4\\n        System.out.println(original_result + \\" * 2 = \\" + result);\\n        original_result = result;\\n\\n        result = result / 2;\\n        // result is now 2\\n        System.out.println(original_result + \\" / 2 = \\" + result);\\n        original_result = result;\\n\\n        result = result + 8;\\n        // result is now 10\\n        System.out.println(original_result + \\" + 8 = \\" + result);\\n        original_result = result;\\n\\n        result = result % 7;\\n        // result is now 3\\n        System.out.println(original_result + \\" % 7 = \\" + result);\\n    }\\n}"}', 20, NOW(6), NOW(6) FROM posts WHERE id = 118 AND slug = 'java-8' AND updated_at = '2026-09-25 12:54:20.296197';
