INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"java","code":"// Stringと他の型の+演算\\nint number = 42;\\nString result = \\"Number: \\" + number;  // 他の型も自動的にStringに変換\\n\\nString str = \\"a\\";\\nSystem.out.println(str + 2);      // \\"a2\\" 出力\\nSystem.out.println(\\"a\\" + 2);      // \\"a2\\" 出力\\n\\nchar c = \'a\';\\nSystem.out.println((char)(c + 2));  // \'c\' 出力\\n// \'a\'(97) + 2 = 99(\'c\')\\n\\n// Stringに変換したい場合\\nString result = String.valueOf((char)(c + 2));  // \\"c\\""}', 30, NOW(6), NOW(6) FROM posts WHERE id = 118 AND slug = 'java-8' AND updated_at = '2026-09-25 12:54:20.296197';
