INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"java","code":"class UnaryDemo {\\n\\n    public static void main(String[] args) {\\n\\n        int result = +1;\\n        // result is now 1\\n        System.out.println(result);\\n\\n        result--;\\n        // result is now 0\\n        System.out.println(result);\\n\\n        result++;\\n        // result is now 1\\n        System.out.println(result);\\n\\n        result = -result;\\n        // result is now -1\\n        System.out.println(result);\\n\\n        boolean success = false;\\n        // false\\n        System.out.println(success);\\n        // true\\n        System.out.println(!success);\\n    }\\n}"}', 33, NOW(6), NOW(6) FROM posts WHERE id = 118 AND slug = 'java-8' AND updated_at = '2026-09-25 12:54:20.296197';
