INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'TABLE', '| 比較演算子 | 説明 |\n| --- | --- |\n| == | 2つの値が同じときに真 |\n| != | 2つの値が異なるときに真 |\n| \\> | 最初の値が2番目の値より大きいときに真 |\n| \\>= | 最初の値が2番目の値以上のときに真 |\n| < | 最初の値が2番目の値より小さいときに真 |\n| <= | 最初の値が2番目の値以下のときに真 |', 40, NOW(6), NOW(6) FROM posts WHERE id = 118 AND slug = 'java-8' AND updated_at = '2026-09-25 12:54:20.296197';
