INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'TABLE', '| 演算子 | 説明 |\n| --- | --- |\n| & | 両方のビットが1のときのみ1 (AND) |\n| \\| | どちらかのビットが1であれば1 (OR) |\n| ^ | ビットが異なるとき1 (XOR) |\n| \\~ | ビット値を反転 (NOT) |\n| << | 左にビットを移動 (LEFT SHIFT) |\n| \\>> | 右にビットを移動 (RIGHT SHIFT) |\n| \\>>> | 右にビットを移動（0で埋める） |', 63, NOW(6), NOW(6) FROM posts WHERE id = 118 AND slug = 'java-8' AND updated_at = '2026-09-25 12:54:20.296197';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\n// & (AND 演算)\\n5 の表現:  00000000 00000000 00000000 00000101\\n3 の表現:  00000000 00000000 00000000 00000011\\n5 & 3:  00000000 00000000 00000000 00000001  // 結果: 1（両方が1のビットのみ1）\\n\\n// | (OR 演算)\\n5 の表現:  00000000 00000000 00000000 00000101\\n3 の表現:  00000000 00000000 00000000 00000011\\n5 | 3:  00000000 00000000 00000000 00000111  // 結果: 7（どちらかが1なら1）\\n\\n// ^ (XOR 演算)\\n5 の表現:  00000000 00000000 00000000 00000101\\n3 の表現:  00000000 00000000 00000000 00000011\\n5 ^ 3:  00000000 00000000 00000000 00000110  // 結果: 6（異なるビットは1）\\n\\n// << (左シフト)\\n5 の表現:  00000000 00000000 00000000 00000101\\n5 << 1:   00000000 00000000 00000000 00001010  // 結果: 10（左に1ビットシフト、右は0）\\n\\n// >> (符号付き右シフト)\\n-8 の表現: 11111111 11111111 11111111 11111000\\n-8 >> 1:   11111111 11111111 11111111 11111100  // 結果: -4（符号ビット1を維持）\\n\\n// >>> (符号なし右シフト)\\n-8 の表現:  11111111 11111111 11111111 11111000\\n-8 >>> 1:   01111111 11111111 11111111 11111100  // 結果: 2147483644（必ず0で埋める）"}', 64, NOW(6), NOW(6) FROM posts WHERE id = 118 AND slug = 'java-8' AND updated_at = '2026-09-25 12:54:20.296197';
