INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\nclass InstanceofDemo {\\n    public static void main(String[] args) {\\n\\n        Parent obj1 = new Parent();\\n        Parent obj2 = new Child();\\n\\n        System.out.println(\\"obj1 instanceof Parent: \\"\\n            + (obj1 instanceof Parent));\\n        System.out.println(\\"obj1 instanceof Child: \\"\\n            + (obj1 instanceof Child));\\n        System.out.println(\\"obj1 instanceof MyInterface: \\"\\n            + (obj1 instanceof MyInterface));\\n        System.out.println(\\"obj2 instanceof Parent: \\"\\n            + (obj2 instanceof Parent));\\n        System.out.println(\\"obj2 instanceof Child: \\"\\n            + (obj2 instanceof Child));\\n        System.out.println(\\"obj2 instanceof MyInterface: \\"\\n            + (obj2 instanceof MyInterface));\\n    }\\n}\\n\\nclass Parent {}\\nclass Child extends Parent implements MyInterface {}\\ninterface MyInterface {}"}', 69, NOW(6), NOW(6) FROM posts WHERE id = 118 AND slug = 'java-8' AND updated_at = '2026-09-25 12:54:20.296197';
