INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\n// Bad: 副作用があるコード\\nint sum = 0;\\nlist.forEach(num -> {\\n    sum += num;  // 外部変数を変更（副作用）\\n});\\n\\n// Good: 副作用のないコード\\nint sum = list.stream()\\n             .reduce(0, (a, b) -> a + b);  // 外部変数の変更なし\\n\\n```java\\n// アロー演算子(->)を使用したラムダ式のさまざまな形\\n(引数) -> { 実行文; }  // 基本形\\n() -> System.out.println(\\"Hello\\")  // 引数なし\\nx -> x * x  // 引数が1つのときは括弧省略可能\\n(a, b) -> a + b  // 引数が複数"}', 73, NOW(6), NOW(6) FROM posts WHERE id = 118 AND slug = 'java-8' AND updated_at = '2026-09-25 12:54:20.296197';
