INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- Enum のデフォルトコンストラクタは常に `private` です（コンパイラによって強制的に `private` に設定されます）。\n- Enum はフィールドを持つことができます。\n- 各定数はコンストラクタを通じて対応するフィールドを初期化することができます。', 11, NOW(6), NOW(6) FROM posts WHERE id = 100 AND slug = 'java-enum' AND updated_at = '2026-07-15 15:18:27.172785';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"java","code":"enum Color {\\n    RED(\\"赤色\\"), GREEN(\\"緑色\\"), BLUE(\\"青色\\");\\n\\n    private final String description; // フィールドの定義\\n\\n    // コンストラクタの定義\\n    private Color(String description) {\\n        this.description = description;\\n    }\\n\\n    // フィールドの getter メソッド\\n    public String getDescription() {\\n        return description;\\n    }\\n}\\n\\npublic class Main {\\n    public static void main(String[] args) {\\n        System.out.println(Color.RED.getDescription()); // \\"赤色\\" を出力\\n        System.out.println(Color.GREEN.getDescription()); // \\"緑色\\" を出力\\n    }\\n}"}', 12, NOW(6), NOW(6) FROM posts WHERE id = 100 AND slug = 'java-enum' AND updated_at = '2026-07-15 15:18:27.172785';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'H2', 'メソッドの定義', 13, NOW(6), NOW(6) FROM posts WHERE id = 100 AND slug = 'java-enum' AND updated_at = '2026-07-15 15:18:27.172785';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- Enum に一般的なメソッドを定義することができます\n- すべての定数で共通して使用するメソッドを定義したり、特定の定数でのみオーバーライドするように設定することもできます', 14, NOW(6), NOW(6) FROM posts WHERE id = 100 AND slug = 'java-enum' AND updated_at = '2026-07-15 15:18:27.172785';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"java","code":"enum Operation {\\n    ADD {\\n        @Override\\n        public int apply(int x, int y) {\\n            return x + y;\\n        }\\n    },\\n    SUBTRACT {\\n        @Override\\n        public int apply(int x, int y) {\\n            return x - y;\\n        }\\n    },\\n    MULTIPLY {\\n        @Override\\n        public int apply(int x, int y) {\\n            return x * y;\\n        }\\n    };\\n\\n    // 抽象メソッドの宣言（定数ごとに実装）\\n    public abstract int apply(int x, int y);\\n}\\n\\npublic class Main {\\n    public static void main(String[] args) {\\n        System.out.println(Operation.ADD.apply(3, 4)); // 7\\n        System.out.println(Operation.SUBTRACT.apply(10, 5)); // 5\\n        System.out.println(Operation.MULTIPLY.apply(2, 3)); // 6\\n    }\\n}"}', 15, NOW(6), NOW(6) FROM posts WHERE id = 100 AND slug = 'java-enum' AND updated_at = '2026-07-15 15:18:27.172785';
