INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"java","code":"enum Color {\\n    RED, GREEN, BLUE;\\n\\n    public static Color fromString(String colorName) {\\n        return switch (colorName.toUpperCase()) {\\n            case \\"RED\\" -> RED;\\n            case \\"GREEN\\" -> GREEN;\\n            case \\"BLUE\\" -> BLUE;\\n            default -> throw new IllegalArgumentException(\\"不明な色: \\" + colorName);\\n        };\\n    }\\n}\\n\\npublic class Main {\\n    public static void main(String[] args) {\\n        Color color = Color.fromString(\\"red\\");\\n        System.out.println(color); // RED を出力\\n    }\\n}"}', 18, NOW(6), NOW(6) FROM posts WHERE id = 100 AND slug = 'java-enum' AND updated_at = '2026-07-15 15:18:27.172785';
