INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"java","code":"package com.example.jpystudy;\\n\\nimport java.lang.constant.ClassDesc;\\nimport java.lang.invoke.MethodHandles;\\n\\nimport java.io.*;\\n\\nenum Color {\\n    RED, GREEN, BLUE\\n}\\n\\npublic class Main {\\n    public static void main(String[] args) throws Exception {\\n        // シリアライズ\\n        Color color = Color.RED;\\n        ByteArrayOutputStream byteOut = new ByteArrayOutputStream();\\n        ObjectOutputStream out = new ObjectOutputStream(byteOut);\\n        out.writeObject(color);\\n\\n        // デシリアライズ\\n        ByteArrayInputStream byteIn = new ByteArrayInputStream(byteOut.toByteArray());\\n        ObjectInputStream in = new ObjectInputStream(byteIn);\\n        Color deserializedColor = (Color) in.readObject();\\n\\n        // 比較\\n        System.out.println(color == deserializedColor); // true (シングルトン保証)\\n    }\\n}"}', 89, NOW(6), NOW(6) FROM posts WHERE id = 100 AND slug = 'java-enum' AND updated_at = '2026-07-15 15:18:27.172785';
