INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- EnumSetは内部的に上記のビット演算を活用し、列挙型定数を効率的に管理します\n- EnumSetを使用することで、型安全にEnumの集合を扱うことができます', 106, NOW(6), NOW(6) FROM posts WHERE id = 100 AND slug = 'java-enum' AND updated_at = '2026-07-15 15:18:27.172785';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"java","code":"\\nenum Color {\\n        RED, GREEN, BLUE, YELLOW;\\n    }\\n    \\n    public class Main {\\n    public static void main(String[] args) {\\n        EnumSet<Color> colors = EnumSet.noneOf(Color.class); // 空のセットを生成\\n\\n        // REDを追加\\n        colors.add(Color.RED); // 内部的に bitVector |= RED\\n        System.out.println(colors); // [RED]\\n\\n        // GREENを追加\\n        colors.add(Color.GREEN); // 内部的に bitVector |= GREEN\\n        System.out.println(colors); // [RED, GREEN]\\n\\n        // REDを削除\\n        colors.remove(Color.RED); // 内部的に bitVector &= ~RED\\n        System.out.println(colors); // [GREEN]\\n\\n        // 含有判定\\n        boolean containsBlue = colors.contains(Color.BLUE); // 内部的に bitVector & BLUE\\n        System.out.println(containsBlue); // false\\n    }\\n}\\n    "}', 107, NOW(6), NOW(6) FROM posts WHERE id = 100 AND slug = 'java-enum' AND updated_at = '2026-07-15 15:18:27.172785';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'QUOTE', '[!NOTE]\n**ビット演算を活用したEnum定数の管理**', 108, NOW(6), NOW(6) FROM posts WHERE id = 100 AND slug = 'java-enum' AND updated_at = '2026-07-15 15:18:27.172785';
