INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"java","code":"enum DayOfWeek {\\n    MONDAY, TUESDAY, WEDNESDAY, THURSDAY, FRIDAY, SATURDAY, SUNDAY\\n}\\n\\npublic class Main {\\n    public static void main(String[] args) {\\n        EnumSet<DayOfWeek> weekdays = EnumSet.of(\\n                DayOfWeek.MONDAY,\\n                DayOfWeek.TUESDAY,\\n                DayOfWeek.WEDNESDAY,\\n                DayOfWeek.THURSDAY,\\n                DayOfWeek.FRIDAY\\n        );\\n\\n        weekdays.add(DayOfWeek.SATURDAY);\\n        weekdays.remove(DayOfWeek.MONDAY);\\n\\n        boolean containsSaturday = weekdays.contains(DayOfWeek.SATURDAY);\\n        boolean containsMonday = weekdays.contains(DayOfWeek.MONDAY);\\n\\n        System.out.println(containsSaturday);\\n        System.out.println(containsMonday);\\n    }\\n}"}', 113, NOW(6), NOW(6) FROM posts WHERE id = 100 AND slug = 'java-enum' AND updated_at = '2026-07-15 15:18:27.172785';
