INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- この概念はDomain-Driven Design（DDD）を通じて登場しました\n- オブジェクトのコレクション（Collection）を模倣する保存、取得、および検索動作をカプセル化するメカニズムを提供いたします\n  - カプセル化とは、保存、取得、検索などの内部動作を隠蔽し、Javaのメモリ上で管理することを意味します（例：List、Setなど）', 15, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
