INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'QUOTE', 'Teams implementing traditional Jakarta EE patterns such as "Data Access Object" may also apply this stereotype to DAO classes, though care should be taken to understand the distinction between Data Access Object and DDD-style repositories before doing so. This annotation is a general-purpose stereotype and individual teams may narrow their semantics and use as appropriate.', 25, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
