INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"java","code":"@Commpont\\npublic class UserDao {\\n\\n    private final JdbcTemplate jdbcTemplate;\\n\\n    public UserDao(JdbcTemplate jdbcTemplate) {\\n        this.jdbcTemplate = jdbcTemplate;\\n    }\\n\\n    public List<User> findByName(String name) {\\n        String sql = \\"SELECT id, name FROM users WHERE name = ?\\";\\n        return jdbcTemplate.query(sql, new Object[]{name}, new RowMapper<User>() {\\n            @Override\\n            public User mapRow(ResultSet rs, int rowNum) throws SQLException {\\n                User user = new User();\\n                user.setId(rs.getLong(\\"id\\"));\\n                user.setName(rs.getString(\\"name\\"));\\n                return user;\\n            }\\n        });\\n    }\\n}"}', 34, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
