INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- **DB呼び出しの最小化**: 同一エンティティを再度取得する際にキャッシュ済みのオブジェクトを利用することで、不要なデータベースクエリを削減します\n- **データ整合性の維持**: 同一エンティティに対して同一のインスタンスを再利用することで、データ状態の一貫性が保証されます\n- **パフォーマンスの向上**: DBアクセスの回数を減らすことで、アプリケーション全体のパフォーマンスが向上します', 72, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
