INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '一般的にJPA（またはHibernate）を使用する際は、トランザクションの範囲の設定が非常に重要です。\\\nJPAで言う「**作業単位 (Unit of Work)**」とは、エンティティの生成、修正、削除といった一連の操作を一つの論理的なグループとしてまとめて処理することを意味いたします。', 90, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'この作業単位は通常、データベーストランザクションと同じ範囲に設定する必要があり、これによりデータの整合性と一貫性が維持されます。', 91, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"java","code":" @Transactional\\n    public Student registerStudent(String name) {\\n        Student student = new Student();\\n        student.setName(name);\\n        studentRepository.save(student); \\n        return student;\\n    }"}', 92, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- Springでは、`@Transactional`アノテーションを用いて作業単位を定義し、データベースのライフサイクルとJPAのエンティティライフサイクル（Transient、Managed、Detached、Removed）を一致させることが可能です', 93, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
