INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"markdown","code":"[永続性コンテキスト]\\n┌───────────────────────────────────────────────┐\\n│                                               │\\n│  [1次キャッシュ]                              │\\n│  ┌─────────────────┐                         │\\n│  │                 │                         │\\n│  │  @Id | Entity   │                         │\\n│  │   1  | User     │ ← DBから取得したIDが割り当てられる │\\n│  │                 │                         │\\n│  └─────────────────┘                         │\\n│                                               │\\n│  [書き込み遅延SQLストア]                      │\\n│  ┌─────────────────┐                         │\\n│  │                 │                         │\\n│  │  INSERT SQL     │                         │\\n│  │  即時実行       │ ← すぐにDBにSQLが実行される       │\\n│  │                 │                         │\\n│  └─────────────────┘                         │\\n│                                               │\\n└───────────────────────────────────────────────┘"}', 130, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
