INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- **問題点 1: Extended Persistence Context の問題**\n\n  IDENTITY カラムは、エンティティが実際にデータベースに挿入されるまで識別子の値が決定されません。\\\n  そのため、長期間にわたって複数のエンティティを管理する Extended Persistence Context（拡張永続性コンテキスト）の場合、挿入タイミングに制約が生じ、状態管理に問題が発生する可能性がございます。', 135, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- **問題点 2: バッチ INSERT 処理が不可能**\n\n  IDENTITY 戦略を使用すると、各エンティティの挿入ごとに識別子生成が必要となるため、Hibernateは複数のINSERT文を一度にバッチ処理することができません。\\\n  その結果、大量のエンティティを一括挿入する際、パフォーマンス向上の効果を得にくくなります。', 136, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'それでは、他の生成戦略はどうでしょうか？', 137, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
