INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'TABLE', '| 生成戦略 | 識別子生成クエリ | 識別子生成時点 | INSERTクエリ | 書き込み遅延サポート |\n| --- | --- | --- | --- | --- |\n| IDENTITY | INSERT | persist() 即時 | persist() 即時 | ❌ |\n| SEQUENCE | SELECT NEXT VALUE | persist() 即時 | commit 時点 | ⭕ |\n| TABLE | SELECT & UPDATE | persist() 即時 | commit 時点 | ⭕ |\n| UUID | なし（アプリケーション） | persist() 即時 | commit 時点 | ⭕ |\n| AUTO | 方言により決定 | 方言により決定 | 方言により決定 | \\- |', 143, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
