INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_NUMBERED', '1. 永続性コンテキストは、Studentエンティティを管理するために識別子が必要です。\n2. @SequenceGeneratorに指定された "STUDENT_SEQ" から次の値を取得します。\\\n   -> SQL: `select next value for STUDENT_SEQ`\n3. 取得した識別子の値をStudentエンティティに割り当てます。\n4. Studentエンティティを永続性コンテキストの1次キャッシュに保存します。\n5. INSERT SQLは書き込み遅延ストアに保持されます。', 151, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
