INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_NUMBERED', '1. id_gen テーブルから、特定の GEN_NAME を持つ行の現在の識別子値（GEN_VAL）を読み込みます。\\\n   同時に、`for update` を使用してこの行に対してロックをかけます。', 162, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"sql","code":"update id_gen \\nset GEN_VAL=?  \\nwhere GEN_VAL=? \\n  and GEN_NAME=?"}', 163, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_NUMBERED', '2. 先に読み込んだ値を元に、新しい識別子値へ更新します。', 164, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
