INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '直接値を読み込み、更新する過程でロックが使用されます。\\\nそのため、同時実行性が高い環境ではロック競合および追加のデータベース呼び出しが発生し、パフォーマンス低下につながる可能性がございます。', 167, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
