INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'IMAGE', '{"url":"https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/dd40a9e2-0f26-4584-a539-a36a1d7b3652.png","alt":"image.png"}', 169, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- TABLE ジェネレータは、複数のデータベースで同一に使用できるという利点（移植性）がありますが、実際には識別子値を生成するために別のテーブルを使用します\n- この別テーブルから次の識別子値を取得するために、別のトランザクションを実行し、そのテーブルの特定の行に対して **行レベルロック（row-level lock）** をかける必要があります', 170, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'これらの理由から、Table 戦略は十分に注意して使用する必要がございます。', 171, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
