INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- 永続状態にするためには、Identity Mapで識別するための`@Id`（識別子）が必要です\n- 識別子がデータベース依存の方式であれば、DBにクエリが発生し、\n- アプリケーション依存の方式であれば、クエリは発生しません', 178, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
