INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '#### 代理キー (Surrogate Key) vs 自然キー (Natural Key)', 180, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- **代理キー (Surrogate Key)** : ビジネス上の意味を持たない識別子\n\n  - 下記のテーブル構造において、`id` は学生の意味とは全く関係がありません\n\n  ```java\n  @Entity\n  public class Student {\n      @Id\n      @GeneratedValue(strategy = GenerationType.IDENTITY) \n      private Long id;\n  \n      private String name;\n  }\n  ```', 181, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- **自然キー (Natural Key)** : ビジネス上の意味を持つ識別子\n\n  - 下記のテーブル構造において、`studentNumber` はビジネス上の意味を持っています', 182, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
