INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"@Id\\n@NaturalId  // Hibernateでは自然キーとして認識\\n@Column(name = \\"student_number\\", nullable = false, unique = true)\\nprivate Long studentNumber;"}', 185, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"> ℹ️ **Note**\\n\\n**代理キーを使用すべき理由**\\n- ビジネス（ドメイン）は常に変化しうるためです\\n- もし自然キーが複雑な場合、インデックス作成などデータベース側の問題に柔軟に対応できなくなります\\n\\nこのような理由から、代理キーを使用することが望ましいと考えられます。\\n\\n#### 単純キー (Simple Key) と複合キー (Compound Key)\\n- **単純キー (Simple Key)**: 識別子が1つの場合"}', 186, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
