INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"@Id\\nprivate String department;    // 例: 学科コード\\n\\n@Id\\nprivate String studentNumber;   // 例: 学籍番号"}', 191, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"> ℹ️ **Note**\\n\\n**単純キーを複合キーより好む理由**\\n- ビジネス（ドメイン）は常に変更される可能性があります\\n- エンティティ間の関係設定の観点でも、単純キーの方が一貫性があり、直感的に管理できます\\n\\nこのような理由から、単純キーを好むと考えられます。\\n\\n#### 生成キー (Generated Key) vs 割り当てキー (Assigned Key)\\n- **生成キー (Generated Key)**: JPAまたはDBが生成するキー  "}', 192, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
