INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"  // データベースが自動的に生成するキー（例：auto-increment）\\n  @Id\\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\\n  private Long id;"}', 194, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
