INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '@Entity\\\npublic class Student {\\\n// アプリケーションで直接割り当てるキー（例: 学籍番号）\\\n@Id\\\n@NaturalId // Hibernateでは自然キーとしても使用\\\n@Column(name = "student_number", nullable = false, unique = true)\\\nprivate Long studentNumber;', 197, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\n> ℹ️ **Note**\\n\\n**生成キーを好む理由**\\n- 管理や安定性の観点から、生成キー方式は直感的です\\n- ビジネス（ドメイン）は常に変更される可能性があるためです\\n\\nこのような理由から、生成キー方式が優れていると考えられます。\\n\\n\\n### find(); を使用して 1次キャッシュとDBからデータを取得する\\n\\n![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/91fc7dca-56cc-4816-8de7-56733aeee19b.png)\\n\\n`find();` を使用して、DBからデータを取得し、1次キャッシュに保持する方法があります。\\n\\n動作は次の通りです。\\n\\n1. 1次キャッシュ（Identity Map）に対象のオブジェクトが存在するかを確認します\\n\\n   ![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/9328b4f1-bc7d-4c2d-9c88-89575ecf0b46.png)\\n   \\n   存在すれば、そのオブジェクトを返却します。\\n\\n> ℹ️ **Note**\\n>    1次キャッシュのこの動作により、作業範囲（トランザクション）内では識別子の同一性に応じて同一のオブジェクトが返却されることが保証されます。  \\n>    また、1次キャッシュにオブジェクトが既に存在する場合、SELECTクエリは発生しません。\\n\\n2. もし存在しなければ、データベースに対してSELECTクエリを発行し、データを取得してJavaオブジェクトにマッピングした後、永続性コンテキストに登録し、返却します。\\n\\n   ![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/70772c1d-0357-4d2b-be24-894721c290f6.png)\\n   \\n   ![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/8512b24b-25d4-4ce1-aa95-be78c0cabbd1.png)\\n   \\n   ![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/a8feea77-40bf-492f-bd5c-092c29d2b6b1.png)\\n\\nもしDBにも存在しなければ、nullが返されます。\\n\\n\\n## Removed 状態\\n\\n![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/4075a530-67ed-4845-bf0c-17d8d8d23f5f.png)\\n\\n`remove();` メソッドを通じ、永続状態のエンティティを削除対象としてマークすることができます。\\n\\n- 次に `flush();` を呼び出すと、データベースに対して DELETE クエリが発行され、実際に削除されます\\n- `remove();` は永続状態にあるエンティティを削除対象に変更するだけであり、依然として永続性コンテキストで管理されるオブジェクトです。\\n- つまり、永続状態でないオブジェクトには `remove();` を使用することはできません\\n\\n> ℹ️ **Note**\\n> つまり、JPAで削除を実行するためには、必ず識別子（@Id）を用いてエンティティを永続状態に登録する必要があるため、ほとんどの場合 `find();` を通じたSELECTクエリが発生します。\\n\\n![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/d08e21e6-c86e-45b4-ab99-2c91081d9628.png)\\n![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/d0ba874b-aea2-44f3-bb77-e1136d90119e.png)\\n`package org.hibernate.event.internal.EntityStatus` を確認すると、動作構造を詳しく把握することができます。\\n\\n以下は、永続状態のエンティティを削除する際の動作を示しています。\\n\\n![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/7f904cb1-106e-4285-9510-ddeeab212375.png)\\n\\n次のようなテストコードがあります。"}', 198, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'Student findStudent = entityManager.find(Student.class, 1L);\\\nentityManager.remove(findStudent);', 199, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"これにより、エンティティが Removed 状態に変更されます。\\nその後、以下のように Removed 状態に設定されたエンティティを取得しようとすると、"}', 200, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'Student removedStudent = entityManager.find(Student.class, student.getId());\\\nassertNull(removedStudent);', 201, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"永続性コンテキスト（1次キャッシュ）からも値は見つかりません。\\n\\n![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/0f432236-211f-424e-9a9d-0bb57ed6e812.png)\\n\\nしかしながら、これはあくまで永続性コンテキスト上で管理されているオブジェクトであり、flush() を呼び出さない限り、データベース上からは削除されません。\\n該当テストコードのログを確認すると、以下のように DELETE クエリは発生していません。\\n\\n![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/6725d7ac-f907-4743-9903-143bf7d77d33.png)\\n\\n\\n### Removed 状態のオブジェクトを再び永続化する\\n\\n通常、Removed 状態になったオブジェクトを再び永続状態に戻すことはほとんどありませんが、理解を深めるために、以下のような状況を考えてみましょう。\\n\\nポイントは、永続性コンテキスト（Identity Map）に登録されているか否かです。  \\n次のようなコードは、\\n\\n![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/545f6f81-afcc-453e-844f-404b72f5bcec.png)"}', 202, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'entityManager.remove(student);', 203, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"状態遷移: **Managed → Removed**  \\n`remove()` を呼び出すと、エンティティの状態は Removed に変更され、削除対象としてマークされます。  \\n（ただし、まだ `flush()` を呼び出していないため、データベース上では実際には削除されていません。）"}', 204, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'entityManager.detach(student);', 205, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"状態遷移: **Removed → Detached**  \\n`detach()` を呼び出すと、永続性コンテキストから該当エンティティが分離され、Detached 状態になります。  \\nこの時点で、削除予約（Removed 状態）はキャンセルされます。"}', 206, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'Student reattachedStudent = entityManager.merge(student);', 207, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"状態遷移: **Detached → Managed**  \\n`merge()` を呼び出すと、Detached 状態のエンティティが再び永続性コンテキストにマージされ、新たな Managed インスタンス（reattachedStudent）が返されます。  \\nこの際、同一の識別子（ID）の値が保持されます。\\n\\n## Destached\\n\\n![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/cc276dd4-462e-49a7-9ca4-088352b3409e.png)\\n\\n以前のテストコードで使用したように、"}', 208, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'entityManager.detach(student);', 209, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"というメソッドを使用しますが、これは永続性コンテキストにおいて該当オブジェクトの管理を中止することを意味いたします。\\n\\nつまり、Identity Map（1次キャッシュ）からそのオブジェクトが除外されます。\\n\\n![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/fb20196f-48b6-4b5b-9429-8ded3e57a783.png)\\nこの後、以下のようなリクエストが発生すると、\\n\\n![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/0d330cbb-a56a-4497-99d6-07e48fd947f0.png)\\n\\n\\n永続性コンテキスト内から対象オブジェクトが除外された状態となります。"}', 210, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'entityManager.clear();', 211, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"다음과 같은 메서드를 쓴다면 영속성 컨텍스트에서 관리되는 모든 객체를 영속성 컨텍스트에서 제거한다.\\n\\n\\n次のようなメソッドを使用すると、永続性コンテキストで管理されているすべてのオブジェクトが永続性コンテキストから除外されます。\\n\\n> ℹ️ **Note**\\n> **非永続状態 (Transient) と 準永続状態 (Detached) の違い**  \\n> 最も大きな違いは、準永続状態では識別子 (id) が存在するため、再登録時に INSERT クエリが発生しないという点です。\\n\\n## flush() メソッド \\n\\n![image.png](https://qiita-image-store.s3.ap-northeast-1.amazonaws.com/0/3815412/21e2bbc5-56bc-4478-a1ef-eead54184ba5.png)\\n\\n- 永続性コンテキストには、元の状態のスナップショットと該当エンティティが保存されています\\n- `flush()` を呼び出すと、メモリ上の変更点を比較し、実際のデータベースに反映するためのクエリが実行されます\\n\\n簡単に言えば、これまでの変更内容をデータベースと同期させる作業であると言えます。\\n\\n\\n次回の記事では、永続性の伝播 (Cascade) について整理いたします。\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n"}', 212, NOW(6), NOW(6) FROM posts WHERE id = 103 AND slug = 'jpa' AND updated_at = '2026-08-05 14:39:51.572574';
