INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '現在のプロジェクトで簡単なモニタリングツールとしてNetdataを導入することに決定しましたが、ポート19999が外部に公開される問題がありました。これを解決するために、.htpasswdファイルを使用してNginxを介してNetdataへのアクセスを制限する方法を適用しました。この方法で、認証されたユーザーのみがNetdataダッシュボードにアクセスできるように設定しました。', 2, NOW(6), NOW(6) FROM posts WHERE id = 123 AND slug = 'nginx-htpasswd' AND updated_at = '2026-09-24 20:43:21.154319';
