INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'まず、Netdataダッシュボードへのアクセスを制限するために.htpasswdファイルを作成する必要があります。そのためには、apache2-utilsパッケージをインストールする必要があります。', 8, NOW(6), NOW(6) FROM posts WHERE id = 123 AND slug = 'nginx-htpasswd' AND updated_at = '2026-09-24 20:43:21.154319';
