INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'LIST_BULLET', '- htpasswdは、HTTPユーザーの基本認証のために、ユーザー名とパスワードを保存するプレーンテキストファイルを作成および更新するツールです\n- パスワードはbcrypt、MD5、SHA-1、またはシステムのcrypt()関数を使用して暗号化されます。このツールは、プレーンテキストファイルでのみユーザー名とパスワードを管理し、ファイルにアクセスできない場合はエラーを返します', 16, NOW(6), NOW(6) FROM posts WHERE id = 123 AND slug = 'nginx-htpasswd' AND updated_at = '2026-09-24 20:43:21.154319';
