INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":"diff","code":" nginx:\\n    image: nginx:latest\\n    ports:\\n      - \\"80:80\\"\\n      - \\"443:443\\"\\n    volumes:\\n      - ./nginx.conf:/etc/nginx/nginx.conf:ro\\n      - certbot_conf:/etc/letsencrypt\\n      - certbot_www:/var/www/certbot\\n      - /etc/timezone:/etc/timezone:ro\\n      - /etc/localtime:/etc/localtime:ro\\n+     - ./.htpasswd:/etc/nginx/.htpasswd:ro\\n    environment:\\n      - TZ=Asia/Seoul\\n    command: \\"/bin/sh -c \'while :; do sleep 6h & wait $$' '{!}; nginx -s reload; done & nginx -g \\\\\\"daemon off;\\\\\\"\'\\"\\n    networks:\\n      - hubo-network"}', 21, NOW(6), NOW(6) FROM posts WHERE id = 123 AND slug = 'nginx-htpasswd' AND updated_at = '2026-09-24 20:43:21.154319';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', '現在、.htpasswdファイルを生成したパスに合わせて、Docker Composeファイルでそのファイルをnginxコンテナにマッピングするために、コンテナ内部の/etc/nginx/.htpasswdパスに読み取り専用でマッピングされるように設定しました。', 22, NOW(6), NOW(6) FROM posts WHERE id = 123 AND slug = 'nginx-htpasswd' AND updated_at = '2026-09-24 20:43:21.154319';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'CODE', '{"lang":null,"code":"\\tlocation /netdata/ {\\n    \\t\\tauth_basic \\"Administrator\'s Area\\";\\n    \\t\\tauth_basic_user_file /etc/nginx/.htpasswd;\\n    \\t\\tproxy_pass http://hubo-netdata:19999/;\\n    \\t\\tproxy_set_header Host $host;\\n    \\t\\tproxy_set_header X-Forwarded-Host $host;\\n    \\t\\tproxy_set_header X-Forwarded-Server $host;\\n    \\t\\tproxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\\n    \\t\\tproxy_http_version 1.1;\\n    \\t\\tproxy_pass_request_headers on;\\n    \\t\\tproxy_set_header Connection \\"keep-alive\\";\\n \\t   \\tproxy_store off;\\n\\t}"}', 23, NOW(6), NOW(6) FROM posts WHERE id = 123 AND slug = 'nginx-htpasswd' AND updated_at = '2026-09-24 20:43:21.154319';
INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'PARAGRAPH', 'Nginx設定ファイルを通じてNetdataダッシュボードへのアクセスを保護するために基本認証を追加し、/netdata/パスへのリクエストをNetdataサービスにプロキシして転送するようにしました。', 24, NOW(6), NOW(6) FROM posts WHERE id = 123 AND slug = 'nginx-htpasswd' AND updated_at = '2026-09-24 20:43:21.154319';
