INSERT INTO post_block (post_id, block_type, content, block_order, created_at, updated_at) SELECT id, 'QUOTE', '⚠️ **注意**\\\n**なぜdocker restartコマンドを使用しないのですか？**\\\ndocker restartは既存のコンテナを停止して再起動するだけなので、コンテナの設定やファイルシステムに対する変更が適用されません。', 28, NOW(6), NOW(6) FROM posts WHERE id = 123 AND slug = 'nginx-htpasswd' AND updated_at = '2026-09-24 20:43:21.154319';
